import { IConnection } from "@nestia/fetcher";
import { PlainFetcher } from "@nestia/fetcher/lib/PlainFetcher";
import typia from "typia";

import { IDiscussionBoardMember } from "../../structures/IDiscussionBoardMember";

/**
 * Verifies the validity of the current guest session and returns session status
 * information. This public endpoint does not require authentication but returns
 * information about the temporary session.
 *
 * @param props.connection
 * @path /guest/verify
 * @accessor api.functional.guest.verify
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export async function verify(
  connection: IConnection,
): Promise<verify.Response> {
  return true === connection.simulate
    ? verify.simulate(connection)
    : await PlainFetcher.fetch(
        {
          ...connection,
          headers: {
            ...connection.headers,
            "Content-Type": "application/json",
          },
        },
        {
          ...verify.METADATA,
          path: verify.path(),
          status: null,
        },
      );
}
export namespace verify {
  export type Response = IDiscussionBoardMember.IStatus;

  export const METADATA = {
    method: "GET",
    path: "/guest/verify",
    request: null,
    response: {
      type: "application/json",
      encrypted: false,
    },
  } as const;

  export const path = () => "/guest/verify";
  export const random = (): IDiscussionBoardMember.IStatus =>
    typia.random<IDiscussionBoardMember.IStatus>();
  export const simulate = (_connection: IConnection): Response => {
    return random();
  };
}
